const importId = 'basemap';
const schema = (typeof map.getSchema === 'function' && map.getSchema(importId)) || {};
let keys = Object.keys(schema).filter(k => /lane/i.test(k) || /road.*detail|detail.*road/i.test(k));
if (keys.length === 0) keys = ['showLaneMarkings'];
keys.forEach(k => {
  const def = schema[k] || {};
  let value = true;
  if (Array.isArray(def.values) && def.values.length) {
    value = def.values.find(v => /lane|detail|full|high|all/i.test(String(v))) ?? def.values[def.values.length - 1];
  } else if (def.type === 'number' || typeof def.default === 'number') {
    value = typeof def.maxValue === 'number' ? def.maxValue : 1;
  }
  map.setConfigProperty(importId, k, value);
});

