const schema = (typeof map.getSchema === 'function' && map.getSchema(importId)) || {};
const laneColorKeys = Object.keys(schema).filter(k => /lane/i.test(k) && (/colou?r/i.test(k) || (schema[k] && schema[k].type === 'color')) && !/mark|line|label|arrow|stripe/i.test(k));
if (laneColorKeys.length) {
  laneColorKeys.forEach(k => map.setConfigProperty(importId, k, '#555555'));
} else {
  ['colorRoadLanes', 'colorLanes', 'colorLaneSurface', 'colorRoadSurfaceLanes'].forEach(k => {
    try { map.setConfigProperty(importId, k, '#555555'); } catch (e) {}
  });
}

